 * the directory named by the export. The leaves of the tree are files of
 * exactly TREEPAGESIZE bytes each, and every directory in the tree holds
 * at most TREEDIRSIZE entries. Data at a given offset of the export is
 * stored in the leaf file that corresponds to the TREEPAGESIZE-sized
 * block containing that offset; the nesting depth is chosen so that all
 * blocks of a filesystem of the configured size can be addressed.
 *
 * Leaf files and directories are created on demand, i.e. when data is
 * first written to a block. Blocks that have never been written read as
 * zeroes, since the leaf file does not exist (or is shorter than a full
 * block).
 */

#include "config.h"
#include "nbd-debug.h"

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include <nbdsrv.h>
#include <treefiles.h>
#include <cliserv.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Create the directory `path' if it does not exist yet.
 *
 * Exits with an error if `path' exists but is not a directory, or if the
 * directory cannot be created.
 */
void mkdir_path(char *path) {
	struct stat st;

	if (stat(path, &st) == 0) {
		if (!S_ISDIR(st.st_mode)) {
			err("Tree file path exists but is not a directory");
		}
		return;
	}
	if (mkdir(path, 0700) < 0 && errno != EEXIST) {
		err("Error creating tree file directory: %m");
	}
}

/**
 * Create all directories in `path', which must be the path of a file in
 * the tree (i.e., the last component is not created). Directory creation
 * is serialised with `mutex'.
 */
static void mkdirs(char *path, pthread_mutex_t *mutex) {
	char *p;

	for (p = path + 1; *p != '\0'; p++) {
		if (*p == '/') {
			*p = '\0';
			pthread_mutex_lock(mutex);
			mkdir_path(path);
			pthread_mutex_unlock(mutex);
			*p = '/';
		}
	}
}
```

