void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = 0;
	off_t nblocks;
	off_t capacity;
	off_t block;
	int used;

	if (size <= 0 || pos < 0 || pos >= size) {
		err("Invalid position for tree file");
	}

	nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	capacity = TREEDIRSIZE;
	while (capacity < nblocks) {
		depth++;
		if (capacity > OFFT_MAX / TREEDIRSIZE) {  // hmm, OFFT_MAX is defined in nbd-server.c not a header
			err("Tree too deep");  // or something
		}
		capacity *= TREEDIRSIZE;
	}

	block = pos / TREEPAGESIZE;
	used = strlen(name);
	for (int i = depth; i >= 0; i--) {
		off_t divisor = 1;
		int ret;
		for (int j = 0; j < i; j++)
			divisor *= TREEDIRSIZE;
		ret = snprintf(name + used, lenmax - used, "/%04X",
				(unsigned int)((block / divisor) % TREEDIRSIZE));
		if (ret < 0 || ret >= lenmax - used) {
			err("Tree file path too long");
		}
		used += ret;
	}
	*ppos = pos % TREEPAGESIZE;
}
```

