```c
/**
 * Write an amount of bytes at a given offset to the tree of files that
 * backs a treefiles export, creating files and directories as needed.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
static ssize_t treeexpwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	size_t done = 0;

	while (done < len) {
		off_t pos = a + done;
		off_t ppos = pos % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		int fhandle;
		ssize_t ret;

		if (chunk > len - done)
			chunk = len - done;

		fhandle = open_treefile(client->exportname, O_RDWR | O_CREAT,
					(off_t)client->exportsize,
					pos - ppos, &client->treelock);
		if (fhandle < 0)
			return -1;
		ret = pwrite(fhandle, buf + done, chunk, ppos);
		if (ret == (ssize_t)chunk) {
			if (client->server->flags & F_SYNC) {
				fsync(fhandle);
			} else if (fua) {
				fdatasync(fhandle);
			}
		}
		close(fhandle);
		if (ret != (ssize_t)chunk)
			return -1;
		done += chunk;
	}

	return (ssize_t)done;
}
```

