/**
 * Read an amount of bytes at a given offset from the tree of files that
 * backs a treefiles export. Blocks that have never been written to read
 * as zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t done = 0;

	while(done < len) {
		off_t pos = a + done;
		off_t ppos = pos % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		int fhandle;
		ssize_t ret;

		if(chunk > len - done)
			chunk = len - done;

		fhandle = open_treefile(client->exportname, O_RDONLY,
					(off_t)client->exportsize, pos - ppos,
					&client->treelock);
		if(fhandle < 0) {
			if(errno == ENOENT) {
				/* the block was never written, so it reads
				 * as zeroes */
				memset(buf + done, 0, chunk);
				done += chunk;
				continue;
			}
			return -1;
		}
		ret = pread(fhandle, buf + done, chunk, ppos);
		close(fhandle);
		if(ret < 0)
			return -1;
		if((size_t)ret < chunk) {
			/* reading beyond the end of a partially written
			 * block reads as zeroes */
			memset(buf + done + ret, 0, chunk - ret);
		}
		done += chunk;
	}

	return (ssize_t)done;
}

