/*
 * Tree files support for nbd-server.
 *
 * A treefiles export stores its data in a tree of directories rooted at
 * the directory named by the export. The leaves of the tree are files of
 * TREEPAGESIZE bytes each, and every directory in the tree holds at most
 * TREEDIRSIZE files or subdirectories. The data at a given offset of the
 * export is stored in the leaf file corresponding to the TREEPAGESIZE
 * sized block containing that offset, at the offset of that data within
 * the block. The nesting level of the tree depends on the size of the
 * export and is chosen so that all blocks can be addressed.
 *
 * Leaf files and directories are created on demand, i.e. when data is
 * first written to a block. A block that has never been written to reads
 * as zeroes, since its leaf file does not exist.
 */

#include "config.h"
#include "nbd-debug.h"

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include <nbdsrv.h>
#include <treefiles.h>
#include <cliserv.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Create the directory `path' if it does not exist yet.
 *
 * Exits with an error if `path' exists but is not a directory, or if the
 * directory cannot be created.
 *
 * @param path the directory to create
 */
void mkdir_path(char *path) {
	struct stat st;

	if (stat(path, &st) == 0) {
		if (!S_ISDIR(st.st_mode)) {
			err("Tree files path exists but is not a directory");
		}
		return;
	}
	if (mkdir(path, 0700) < 0 && errno != EEXIST) {
		err("Error creating tree files directory: %m");
	}
}

/**
 * Create all directories of `path', which must be the path of a leaf
 * file in the tree; the last component (the file itself) is not created.
 * Directory creation is serialised with `mutex', since multiple threads
 * may try to create the same directories at the same time.
 *
 * @param path the path of a leaf file in the tree
 * @param mutex lock serialising directory creation
 */
static void mkdirs(char *path, pthread_mutex_t *mutex) {
	char *p;

	for (p = path + 1; *p != '\0'; p++) {
		if (*p == '/') {
			*p = '\0';
			pthread_mutex_lock(mutex);
			mkdir_path(path);
			pthread_mutex_unlock(mutex);
			*p = '/';
		}
	}
}

/**
 * Construct the path to the leaf file that holds the data at a given
 * offset of a treefiles export.
 *
 * The tree has `depth' levels of directories below its root if the
 * number of blocks of the export exceeds TREEDIRSIZE^(depth-1). Every
 * component of the path below the root is the base-TREEDIRSIZE digit of
 * the block number it leads to, formatted as a four digit hexadecimal
 * number.
 *
 * @param name the name of the root of the tree, i.e. the export name.
 *        The full path to the leaf file is written to this buffer.
 * @param lenmax the size of the name buffer
 * @param size the total size of the export
 * @param pos the offset into the export for which to construct the path
 * @param ppos [out] the offset into the leaf file at which the data for
 *        the given offset is stored
 */
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = 0;
	off_t nblocks;
	off_t capacity;
	off_t block;
	int used;
	int i;
	int ret;

	if (size <= 0 || pos < 0 || pos >= size) {
		err("Invalid offset into tree files export");
	}

	nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	capacity = TREEDIRSIZE;
	while (capacity < nblocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}
	DEBUG("Constructing path to file for block %llu, depth %d\n",
	      (unsigned long long)(pos / TREEPAGESIZE), depth);

	block = pos / TREEPAGESIZE;
	used = strlen(name);
	for (i = depth; i >= 0; i--) {
		off_t divisor = 1;
		int j;

		for (j = 0; j < i; j++)
			divisor *= TREEDIRSIZE;
		ret = snprintf(name + used, lenmax - used, "/%04X",
			       (unsigned int)((block / divisor) % TREEDIRSIZE));
		if (ret < 0 || ret >= lenmax - used) {
			err("Path to tree files file is too long");
		}
		used += ret;
	}
	*ppos = pos % TREEPAGESIZE;
}

/**
 * Delete the leaf file that holds the data at a given offset of a
 * treefiles export; e.g. because the block was marked as unused by a
 * TRIM request. It is not an error if the file does not exist.
 *
 * @param name the name of the root of the tree, i.e. the export name
 * @param size the total size of the export
 * @param pos the offset into the export
 */
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];
	off_t ppos;

	if (snprintf(path, sizeof(path), "%s", name) >= (int)sizeof(path)) {
		err("Path to tree files file is too long");
	}
	construct_path(path, sizeof(path), size, pos, &ppos);
	if (unlink(path) < 0 && errno != ENOENT) {
		msg(LOG_WARNING, "Could not delete tree files file %s: %s",
		    path, strerror(errno));
	}
}

/**
 * Open the leaf file that holds the data at a given offset of a
 * treefiles export. If the file is to be created and directories on the
 * path to it do not exist yet, they are created as well.
 *
 * @param name the name of the root of the tree, i.e. the export name
 * @param mode open(2) flags for the leaf file
 * @param size the total size of the export
 * @param pos the offset into the export
 * @param mutex lock serialising directory creation
 * @return a file descriptor for the leaf file, or -1 on failure with
 *         errno set appropriately
 */
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	off_t ppos;
	int fd;

	if (snprintf(path, sizeof(path), "%s", name) >= (int)sizeof(path)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	construct_path(path, sizeof(path), size, pos, &ppos);
	if (mode & O_CREAT) {
		mkdirs(path, mutex);
	}
	fd = open(path, mode, 0600);
	DEBUG("Opening tree files file %s, fd %d\n", path, fd);
	return fd;
}

